after:
/* TASK031: the Android highlight must not paint the larger label rectangle. */
.setup-wizard .finish-choices label{-webkit-tap-highlight-color:transparent}
.setup-wizard .finish-choices label:active>span,
.setup-wizard .finish-choices label.is-pressed>span{background:#284866}

// Presentation cache only: always derive eligibility from the real checker.
const {packPreferences,...stableSettings}=settings;
const stamp={key:JSON.stringify({...stableSettings,...setupSongPolicy(settings)}),cards:PARTY_CARDS,
  questions:QUIP_APPROX_QUESTIONS,packs:QUIP_CONTENT_PACKS,config:getModeConfig,validate:checkContentPack};
let available;
if(useSnapshot&&modeSettingsSnapshot&&Object.keys(stamp).every(key=>stamp[key]===modeSettingsSnapshot[key]))available=modeSettingsSnapshot.available;
else{
  available=false;
  try{available=checkContentPack(options.contentPack,{...settings,...setupSongPolicy(settings)}).available;}catch{}
  modeSettingsSnapshot={...stamp,available};
}

/* One set of mode controls moves between the grid and its settings page. */
.setup-wizard:not(.wizard-mode-center) .wizard-rule{padding:0;border:0}
.setup-wizard:not(.wizard-mode-center) .wizard-rule>header,
.setup-wizard:not(.wizard-mode-center) .wizard-rule-details,
.setup-wizard:not(.wizard-mode-center) .wizard-mode-settings>h3,
.setup-wizard:not(.wizard-mode-center) .wizard-mode-enabled,
.setup-wizard:not(.wizard-mode-center) #wizard-song{display:none}
.setup-wizard.wizard-mode-center #mode-toggles{grid-template-columns:minmax(0,1fr);gap:0}
.setup-wizard.wizard-mode-center #mode-toggles label>.mode-tile{display:none}
.setup-wizard.wizard-mode-center #mode-toggles .mode-choice label{display:flex;align-items:center;gap:12px;min-height:48px;height:auto;padding:10px 0}
.setup-wizard.wizard-mode-center #mode-toggles input{position:static;opacity:1;width:22px;height:22px;flex:0 0 auto;margin:0}
.setup-wizard.wizard-mode-center #mode-toggles label>.wizard-mode-enabled{display:block;min-height:0;padding:0;background:none;border:0;border-radius:0;font-size:13px}
.setup-wizard.wizard-mode-center input:disabled~.wizard-mode-enabled{color:var(--soft);opacity:.65}
.setup-wizard .wizard-rule-details{margin-top:12px}
.setup-wizard .wizard-rule-details>summary{min-height:48px;padding:12px 0;color:var(--cyan);font-size:13px;font-weight:700;cursor:pointer}
.setup-wizard .wizard-rule-details>summary:focus-visible,
.setup-wizard #wizard-extra>summary:focus-visible{outline:3px solid var(--lime);outline-offset:2px;border-radius:3px}
.setup-wizard .wizard-mode-settings>h3{font-size:12px;margin:16px 0 4px;color:var(--soft)}
.setup-wizard #wizard-song{margin-top:8px}

/* Additional rules share the page surface, with quiet row separators. */
.setup-wizard #wizard-extra .modifier-toggle,
.setup-wizard #wizard-extra .modifier-frequency{background:none;border:0;border-radius:0;box-shadow:none;padding:14px 0;margin:0;border-bottom:1px solid #af98ff30}
.setup-wizard #wizard-extra .modifier-toggle>span{min-width:0}
.setup-wizard #wizard-extra .modifier-toggle strong{font-size:13px;line-height:1.5}
.setup-wizard #wizard-extra .modifier-toggle small{display:block;margin-top:4px;font-size:12px;line-height:1.65}

// Press feedback is presentation-only; native radio click/change owns selection.
let pressedFinish=null;
function releaseFinish(){pressedFinish?.classList.remove('is-pressed');pressedFinish=null;}
$('wizard-finish').addEventListener('pointerdown',event=>{
 if(!event.isPrimary||event.button!==0)return;
 const label=event.target.closest('.finish-choices label');
 if(label){releaseFinish();pressedFinish=label;label.classList.add('is-pressed');}
});
document.addEventListener('pointerup',releaseFinish,true);
document.addEventListener('pointercancel',releaseFinish,true);
window.addEventListener('blur',releaseFinish);
$('wizard-back').addEventListener('click',navigateBack);
